// Command gen writes the code generated from ops.Schema: the Go
// constants (ops/schema_gen.go) and the Swift decoder and event encoder
// (hosts/ios/Sources/NuiOps/Ops.swift) and the Kotlin decoder and event
// encoder (hosts/android/nui/src/main/java/dev/nui/Ops.kt). Run it with
// go generate ./ops.
package main

import (
	"bytes"
	"fmt"
	"go/format"
	"log"
	"os"
	"path/filepath"
	"strings"
	"unicode"

	"github.com/egoist/nui/ops"
)

func main() {
	log.SetFlags(0)
	// go generate runs us in the ops directory.
	root := ".."
	if _, err := os.Stat("schema.go"); err != nil {
		log.Fatal("gen: run from the ops directory (go generate ./ops)")
	}
	s := ops.Schema
	write(filepath.Join(".", "schema_gen.go"), goFile(s), true)
	write(filepath.Join(root, "hosts", "ios", "Sources", "NuiOps", "Ops.swift"), swiftFile(s), false)
	write(filepath.Join(root, "hosts", "android", "nui", "src", "main", "java", "dev", "nui", "Ops.kt"), kotlinFile(s), false)
}

func write(path string, src []byte, gofmt bool) {
	if gofmt {
		f, err := format.Source(src)
		if err != nil {
			log.Fatalf("gen: %s: %v\n%s", path, err, src)
		}
		src = f
	}
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		log.Fatal(err)
	}
	if err := os.WriteFile(path, src, 0o644); err != nil {
		log.Fatal(err)
	}
}

const header = "Code generated by go generate ./ops from ops/schema.go; DO NOT EDIT."

var typeNames = map[ops.Type]string{
	ops.TBool: "TBool", ops.TInt: "TInt", ops.TFloat: "TFloat", ops.TString: "TString",
	ops.TColor: "TColor", ops.TEdges: "TEdges", ops.TEnum: "TEnum", ops.TBytes: "TBytes",
}

var payloadNames = map[ops.Payload]string{
	ops.PNone: "PNone", ops.PBool: "PBool", ops.PInt: "PInt", ops.PFloat: "PFloat",
	ops.PString: "PString", ops.PPoint: "PPoint", ops.PEnvironment: "PEnvironment",
	ops.PGesture: "PGesture", ops.PBytes: "PBytes",
}

func goFile(s ops.SchemaDef) []byte {
	var b bytes.Buffer
	p := func(format string, args ...any) { fmt.Fprintf(&b, format, args...) }
	p("// %s\n\npackage ops\n\n", header)

	p("// Kinds.\nconst (\n")
	for i, k := range s.Kinds {
		if k.Doc != "" {
			p("\t// Kind%s: %s.\n", k.Name, k.Doc)
		}
		p("\tKind%s Kind = %d\n", k.Name, i+1)
	}
	p(")\n\n")
	p("var kindNames = [...]string{\"\"")
	for _, k := range s.Kinds {
		p(", %q", k.Name)
	}
	p("}\n\n")
	p("func (k Kind) String() string {\n\tif int(k) < len(kindNames) && k > 0 {\n\t\treturn kindNames[k]\n\t}\n\treturn fmt.Sprintf(\"Kind(%%d)\", k)\n}\n\n")

	p("// Props every kind has.\nconst (\n")
	for i, pr := range s.Common {
		if pr.Doc != "" {
			p("\t// Prop%s: %s.\n", pr.Name, pr.Doc)
		}
		p("\tProp%s PropID = %d\n", pr.Name, i+1)
	}
	p(")\n\n")
	for _, k := range s.Kinds {
		if len(k.Props) == 0 {
			continue
		}
		p("// %s props.\nconst (\n", k.Name)
		for i, pr := range k.Props {
			if pr.Doc != "" {
				p("\t// Prop%s%s: %s.\n", k.Name, pr.Name, pr.Doc)
			}
			p("\tProp%s%s PropID = %d\n", k.Name, pr.Name, ops.FirstKindProp+i)
		}
		p(")\n\n")
	}

	p("var commonProps = [...]propInfo{{}")
	for _, pr := range s.Common {
		p(", {%q, %s}", pr.Name, typeNames[pr.Type])
	}
	p("}\n\n")
	p("var kindProps = [...][]propInfo{nil")
	for _, k := range s.Kinds {
		p(", {")
		for i, pr := range k.Props {
			if i > 0 {
				p(", ")
			}
			p("{%q, %s}", pr.Name, typeNames[pr.Type])
		}
		p("}")
	}
	p("}\n\n")

	p("// Events.\nconst (\n")
	for i, e := range s.Events {
		if e.Doc != "" {
			p("\t// Event%s: %s.\n", e.Name, e.Doc)
		}
		p("\tEvent%s EventKind = %d\n", e.Name, i+1)
	}
	p(")\n\n")
	p("var eventNames = [...]string{\"\"")
	for _, e := range s.Events {
		p(", %q", e.Name)
	}
	p("}\n\n")
	p("var eventPayloads = [...]Payload{0")
	for _, e := range s.Events {
		p(", %s", payloadNames[e.Payload])
	}
	p("}\n\n")
	p("func (e EventKind) String() string {\n\tif int(e) < len(eventNames) && e > 0 {\n\t\treturn eventNames[e]\n\t}\n\treturn fmt.Sprintf(\"Event(%%d)\", e)\n}\n\n")
	p("// EventPayload returns what events of kind e carry.\nfunc EventPayload(e EventKind) Payload {\n\tif int(e) < len(eventPayloads) {\n\t\treturn eventPayloads[e]\n\t}\n\treturn 255\n}\n\n")

	p("// Commands.\nconst (\n")
	for i, c := range s.Commands {
		if c.Doc != "" {
			p("\t// Cmd%s: %s.\n", c.Name, c.Doc)
		}
		p("\tCmd%s CommandID = %d\n", c.Name, i+1)
	}
	p(")\n\n")
	p("var commandNames = [...]string{\"\"")
	for _, c := range s.Commands {
		p(", %q", c.Name)
	}
	p("}\n\n")
	p("func (c CommandID) String() string {\n\tif int(c) < len(commandNames) && c > 0 {\n\t\treturn commandNames[c]\n\t}\n\treturn fmt.Sprintf(\"Command(%%d)\", c)\n}\n\n")

	for _, e := range s.Enums {
		p("type %s int32\n\nconst (\n", e.Name)
		for i, v := range e.Values {
			if i == 0 {
				p("\t%s%s %s = iota\n", e.Name, v, e.Name)
			} else {
				p("\t%s%s\n", e.Name, v)
			}
		}
		p(")\n\n")
	}
	src := b.String()
	src = strings.Replace(src, "package ops\n\n", "package ops\n\nimport \"fmt\"\n\n", 1)
	return []byte(src)
}

var swiftKeywords = map[string]bool{
	"default": true, "return": true, "repeat": true, "in": true, "is": true, "as": true,
	"do": true, "if": true, "else": true, "for": true, "while": true, "switch": true,
	"case": true, "break": true, "continue": true, "func": true, "class": true, "struct": true,
	"enum": true, "protocol": true, "let": true, "var": true, "import": true, "true": true,
	"false": true, "nil": true, "self": true, "super": true, "init": true, "public": true,
}

// lowerCamel turns a Go name into a Swift member name.
func lowerCamel(s string) string {
	if strings.ToUpper(s) == s {
		s = strings.ToLower(s)
	} else {
		r := []rune(s)
		i := 0
		for i < len(r) && unicode.IsUpper(r[i]) {
			i++
		}
		if i > 1 && i < len(r) {
			i-- // "URLField" -> "urlField"
		}
		if i == 0 {
			i = 1
		}
		for j := 0; j < i; j++ {
			r[j] = unicode.ToLower(r[j])
		}
		s = string(r)
	}
	if swiftKeywords[s] {
		return "`" + s + "`"
	}
	return s
}

func swiftFile(s ops.SchemaDef) []byte {
	var b bytes.Buffer
	p := func(format string, args ...any) { fmt.Fprintf(&b, format, args...) }
	p("// %s\n\nimport Foundation\n\n", header)

	p("public enum NuiKind: UInt16 {\n")
	for i, k := range s.Kinds {
		p("    case %s = %d\n", lowerCamel(k.Name), i+1)
	}
	p("\n    public var name: String {\n        switch self {\n")
	for _, k := range s.Kinds {
		p("        case .%s: return %q\n", lowerCamel(k.Name), k.Name)
	}
	p("        }\n    }\n}\n\n")

	p("/// Prop IDs. Common props apply to every kind; each kind's own props\n/// start at %d.\npublic enum NuiProp {\n", ops.FirstKindProp)
	for i, pr := range s.Common {
		p("    public static let %s: UInt16 = %d\n", lowerCamel(pr.Name), i+1)
	}
	for _, k := range s.Kinds {
		if len(k.Props) == 0 {
			continue
		}
		p("\n    public enum %s {\n", k.Name)
		for i, pr := range k.Props {
			p("        public static let %s: UInt16 = %d\n", lowerCamel(pr.Name), ops.FirstKindProp+i)
		}
		p("    }\n")
	}
	p("}\n\n")

	p("public enum NuiEventKind: UInt16 {\n")
	for i, e := range s.Events {
		p("    case %s = %d\n", lowerCamel(e.Name), i+1)
	}
	p("}\n\n")

	p("public enum NuiCommand: UInt16 {\n")
	for i, c := range s.Commands {
		p("    case %s = %d\n", lowerCamel(c.Name), i+1)
	}
	p("}\n\n")

	for _, e := range s.Enums {
		p("public enum Nui%s: Int32 {\n", e.Name)
		for i, v := range e.Values {
			p("    case %s = %d\n", lowerCamel(v), i)
		}
		p("}\n\n")
	}

	b.WriteString(swiftRuntime)

	p("\n/// Encoders for the events hosts send, one per event kind.\npublic enum NuiEvents {\n")
	for i, e := range s.Events {
		name := lowerCamel(e.Name)
		switch e.Payload {
		case ops.PNone:
			p("    public static func %s(_ id: UInt32) -> [UInt8] {\n        var w = NuiWriter(); w.header(id, %d); return w.bytes\n    }\n", name, i+1)
		case ops.PBool:
			p("    public static func %s(_ id: UInt32, _ v: Bool) -> [UInt8] {\n        var w = NuiWriter(); w.header(id, %d); w.u8(v ? 1 : 0); return w.bytes\n    }\n", name, i+1)
		case ops.PInt:
			p("    public static func %s(_ id: UInt32, _ v: Int64) -> [UInt8] {\n        var w = NuiWriter(); w.header(id, %d); w.u64(UInt64(bitPattern: v)); return w.bytes\n    }\n", name, i+1)
		case ops.PFloat:
			p("    public static func %s(_ id: UInt32, _ v: Double) -> [UInt8] {\n        var w = NuiWriter(); w.header(id, %d); w.f64(v); return w.bytes\n    }\n", name, i+1)
		case ops.PString:
			p("    public static func %s(_ id: UInt32, _ v: String) -> [UInt8] {\n        var w = NuiWriter(); w.header(id, %d); w.string(v); return w.bytes\n    }\n", name, i+1)
		case ops.PPoint:
			p("    public static func %s(_ id: UInt32, x: Double, y: Double) -> [UInt8] {\n        var w = NuiWriter(); w.header(id, %d); w.f64(x); w.f64(y); return w.bytes\n    }\n", name, i+1)
		case ops.PEnvironment:
			p("    public static func %s(_ id: UInt32, _ e: NuiEnvironment) -> [UInt8] {\n        var w = NuiWriter(); w.header(id, %d); w.environment(e); return w.bytes\n    }\n", name, i+1)
		case ops.PGesture:
			p("    public static func %s(_ id: UInt32, _ g: NuiGesture) -> [UInt8] {\n        var w = NuiWriter(); w.header(id, %d); w.gesture(g); return w.bytes\n    }\n", name, i+1)
		case ops.PBytes:
			p("    public static func %s(_ id: UInt32, _ v: [UInt8]) -> [UInt8] {\n        var w = NuiWriter(); w.header(id, %d); w.u32(UInt32(v.count)); w.bytes.append(contentsOf: v); return w.bytes\n    }\n", name, i+1)
		}
	}
	p("}\n")
	return b.Bytes()
}

// swiftRuntime is the fixed part of the Swift side: the wire format.
const swiftRuntime = `/// A prop value. Bytes are valid only during the handler call.
public enum NuiValue {
    case bool(Bool)
    case int(Int64)
    case float(Double)
    case string(String)
    case color(UInt64)
    case edges(top: Float, right: Float, bottom: Float, left: Float)
    case enumValue(Int32)
    case bytes(UnsafeRawBufferPointer)

    public var bool: Bool { if case .bool(let v) = self { return v }; return false }
    public var int: Int64 { switch self { case .int(let v): return v; case .enumValue(let v): return Int64(v); default: return 0 } }
    public var float: Double { if case .float(let v) = self { return v }; return 0 }
    public var string: String { if case .string(let v) = self { return v }; return "" }
    public var color: UInt64 { if case .color(let v) = self { return v }; return 0 }
    public var enumValue: Int32 { if case .enumValue(let v) = self { return v }; return 0 }
}

/// Receives decoded ops, in order, on the main thread.
@MainActor public protocol NuiOpHandler: AnyObject {
    func create(_ id: UInt32, kind: UInt16)
    func destroy(_ id: UInt32)
    func insert(_ parent: UInt32, child: UInt32, index: Int)
    func remove(_ parent: UInt32, child: UInt32)
    func setProp(_ id: UInt32, prop: UInt16, value: NuiValue)
    func setFrame(_ id: UInt32, x: Float, y: Float, width: Float, height: Float)
    func listen(_ id: UInt32, event: UInt16)
    func unlisten(_ id: UInt32, event: UInt16)
    func command(_ id: UInt32, command: UInt16, args: UnsafeRawBufferPointer)
    func setRoot(_ id: UInt32)
}

/// Reads the little-endian wire format.
public struct NuiReader {
    public var p: UnsafeRawPointer
    public let end: UnsafeRawPointer

    public init(_ data: UnsafeRawBufferPointer) {
        p = data.baseAddress ?? UnsafeRawPointer(bitPattern: 1)!
        end = p + data.count
    }

    public var atEnd: Bool { p >= end }

    @inline(__always) public mutating func u8() -> UInt8 { let v = p.load(as: UInt8.self); p += 1; return v }
    @inline(__always) public mutating func u16() -> UInt16 { let v = p.loadUnaligned(as: UInt16.self); p += 2; return UInt16(littleEndian: v) }
    @inline(__always) public mutating func u32() -> UInt32 { let v = p.loadUnaligned(as: UInt32.self); p += 4; return UInt32(littleEndian: v) }
    @inline(__always) public mutating func u64() -> UInt64 { let v = p.loadUnaligned(as: UInt64.self); p += 8; return UInt64(littleEndian: v) }
    @inline(__always) public mutating func f32() -> Float { Float(bitPattern: u32()) }
    @inline(__always) public mutating func f64() -> Double { Double(bitPattern: u64()) }
    public mutating func bytes() -> UnsafeRawBufferPointer {
        let n = Int(u32())
        let b = UnsafeRawBufferPointer(start: p, count: n)
        p += n
        return b
    }
    public mutating func string() -> String { String(decoding: bytes(), as: UTF8.self) }

    mutating func value(_ type: UInt8) -> NuiValue {
        switch type {
        case 1: return .bool(u8() != 0)
        case 2: return .int(Int64(bitPattern: u64()))
        case 3: return .float(f64())
        case 4: return .string(string())
        case 5: return .color(u64())
        case 6: return .edges(top: f32(), right: f32(), bottom: f32(), left: f32())
        case 7: return .enumValue(Int32(bitPattern: u32()))
        case 8: return .bytes(bytes())
        default: fatalError("nui: bad value type \(type)")
        }
    }
}

/// Decodes a batch of ops into h.
@MainActor public func nuiDecode(_ data: UnsafeRawBufferPointer, _ h: NuiOpHandler) {
    var r = NuiReader(data)
    let n = r.u32()
    for _ in 0..<n {
        let code = r.u8()
        let id = r.u32()
        switch code {
        case 1: h.create(id, kind: r.u16())
        case 2: h.destroy(id)
        case 3: let child = r.u32(); h.insert(id, child: child, index: Int(r.u32()))
        case 4: h.remove(id, child: r.u32())
        case 5: let prop = r.u16(); h.setProp(id, prop: prop, value: r.value(r.u8()))
        case 6: h.setFrame(id, x: r.f32(), y: r.f32(), width: r.f32(), height: r.f32())
        case 7: h.listen(id, event: r.u16())
        case 8: h.unlisten(id, event: r.u16())
        case 9: let cmd = r.u16(); h.command(id, command: cmd, args: r.bytes())
        case 10: h.setRoot(id)
        default: fatalError("nui: bad op code \(code)")
        }
    }
}

/// What a host reports about its root view (see ops.Environment).
public struct NuiEnvironment: Equatable {
    public var width: Float = 0, height: Float = 0
    public var safeTop: Float = 0, safeRight: Float = 0, safeBottom: Float = 0, safeLeft: Float = 0
    public var keyboard: Float = 0
    public var scale: Float = 1
    public var fontScale: Float = 1
    public var dark = false
    public var locale = ""
    public init() {}
}

/// Writes the little-endian wire format.
public struct NuiWriter {
    public var bytes: [UInt8] = []
    public init() {}
    public mutating func u8(_ v: UInt8) { bytes.append(v) }
    public mutating func u16(_ v: UInt16) { withUnsafeBytes(of: v.littleEndian) { bytes.append(contentsOf: $0) } }
    public mutating func u32(_ v: UInt32) { withUnsafeBytes(of: v.littleEndian) { bytes.append(contentsOf: $0) } }
    public mutating func u64(_ v: UInt64) { withUnsafeBytes(of: v.littleEndian) { bytes.append(contentsOf: $0) } }
    public mutating func f32(_ v: Float) { u32(v.bitPattern) }
    public mutating func f64(_ v: Double) { u64(v.bitPattern) }
    public mutating func string(_ v: String) { let u = Array(v.utf8); u32(UInt32(u.count)); bytes.append(contentsOf: u) }
    public mutating func header(_ id: UInt32, _ kind: UInt16) { u32(id); u16(kind) }
    public mutating func environment(_ e: NuiEnvironment) {
        for f in [e.width, e.height, e.safeTop, e.safeRight, e.safeBottom, e.safeLeft, e.keyboard, e.scale, e.fontScale] { f32(f) }
        u8(e.dark ? 1 : 0)
        string(e.locale)
    }
    public mutating func gesture(_ g: NuiGesture) {
        u8(UInt8(g.state))
        for f in [g.x, g.y, g.translationX, g.translationY, g.velocityX, g.velocityY, g.scale] { f32(f) }
    }
}

/// A pan or pinch (see ops.Gesture), in points relative to the view.
public struct NuiGesture {
    public var state: Int32 = 0
    public var x: Float = 0, y: Float = 0
    public var translationX: Float = 0, translationY: Float = 0
    public var velocityX: Float = 0, velocityY: Float = 0
    public var scale: Float = 1
    public init() {}
}
`

// upperSnake turns a Go name into a Kotlin constant name.
func upperSnake(s string) string {
	var b strings.Builder
	r := []rune(s)
	for i, c := range r {
		if i > 0 && unicode.IsUpper(c) && (unicode.IsLower(r[i-1]) || (i+1 < len(r) && unicode.IsLower(r[i+1]) && unicode.IsUpper(r[i-1]))) {
			b.WriteByte('_')
		}
		b.WriteRune(unicode.ToUpper(c))
	}
	return b.String()
}

func kotlinFile(s ops.SchemaDef) []byte {
	var b bytes.Buffer
	p := func(format string, args ...any) { fmt.Fprintf(&b, format, args...) }
	p("// %s\n\n@file:Suppress(\"unused\")\n\npackage dev.nui\n\nimport java.nio.ByteBuffer\nimport java.nio.ByteOrder\n\n", header)

	p("object NuiKind {\n")
	for i, k := range s.Kinds {
		p("    const val %s = %d\n", upperSnake(k.Name), i+1)
	}
	p("\n    fun name(kind: Int): String = when (kind) {\n")
	for i, k := range s.Kinds {
		p("        %d -> %q\n", i+1, k.Name)
	}
	p("        else -> \"Kind($kind)\"\n    }\n}\n\n")

	p("/** Prop IDs. Common props apply to every kind; each kind's own props start at %d. */\nobject NuiProp {\n", ops.FirstKindProp)
	for i, pr := range s.Common {
		p("    const val %s = %d\n", upperSnake(pr.Name), i+1)
	}
	for _, k := range s.Kinds {
		if len(k.Props) == 0 {
			continue
		}
		p("\n    object %s {\n", k.Name)
		for i, pr := range k.Props {
			p("        const val %s = %d\n", upperSnake(pr.Name), ops.FirstKindProp+i)
		}
		p("    }\n")
	}
	p("}\n\n")

	p("object NuiEventKind {\n")
	for i, e := range s.Events {
		p("    const val %s = %d\n", upperSnake(e.Name), i+1)
	}
	p("}\n\n")
	p("object NuiCommand {\n")
	for i, c := range s.Commands {
		p("    const val %s = %d\n", upperSnake(c.Name), i+1)
	}
	p("}\n\n")
	for _, e := range s.Enums {
		p("object Nui%s {\n", e.Name)
		for i, v := range e.Values {
			p("    const val %s = %d\n", upperSnake(v), i)
		}
		p("}\n\n")
	}
	b.WriteString(kotlinRuntime)
	p("\n/** Encoders for the events hosts send, one per event kind. */\nobject NuiEvents {\n")
	for i, e := range s.Events {
		name := lowerCamel(e.Name)
		name = strings.Trim(name, "`")
		switch e.Payload {
		case ops.PNone:
			p("    fun %s(id: Int): ByteArray = NuiWriter().apply { header(id, %d) }.bytes()\n", name, i+1)
		case ops.PBool:
			p("    fun %s(id: Int, v: Boolean): ByteArray = NuiWriter().apply { header(id, %d); u8(if (v) 1 else 0) }.bytes()\n", name, i+1)
		case ops.PInt:
			p("    fun %s(id: Int, v: Long): ByteArray = NuiWriter().apply { header(id, %d); u64(v) }.bytes()\n", name, i+1)
		case ops.PFloat:
			p("    fun %s(id: Int, v: Double): ByteArray = NuiWriter().apply { header(id, %d); f64(v) }.bytes()\n", name, i+1)
		case ops.PString:
			p("    fun %s(id: Int, v: String): ByteArray = NuiWriter().apply { header(id, %d); string(v) }.bytes()\n", name, i+1)
		case ops.PPoint:
			p("    fun %s(id: Int, x: Double, y: Double): ByteArray = NuiWriter().apply { header(id, %d); f64(x); f64(y) }.bytes()\n", name, i+1)
		case ops.PEnvironment:
			p("    fun %s(id: Int, e: NuiEnvironment): ByteArray = NuiWriter().apply { header(id, %d); environment(e) }.bytes()\n", name, i+1)
		case ops.PGesture:
			p("    fun %s(id: Int, g: NuiGesture): ByteArray = NuiWriter().apply { header(id, %d); gesture(g) }.bytes()\n", name, i+1)
		case ops.PBytes:
			p("    fun %s(id: Int, v: ByteArray): ByteArray = NuiWriter().apply { header(id, %d); u32(v.size); raw(v) }.bytes()\n", name, i+1)
		}
	}
	p("}\n")
	return b.Bytes()
}

// kotlinRuntime is the fixed part of the Kotlin side: the wire format.
const kotlinRuntime = `/** Receives decoded ops, in order, on the main thread. */
interface NuiOpHandler {
    fun create(id: Int, kind: Int)
    fun destroy(id: Int)
    fun insert(parent: Int, child: Int, index: Int)
    fun remove(parent: Int, child: Int)
    fun setBool(id: Int, prop: Int, v: Boolean)
    fun setInt(id: Int, prop: Int, v: Long)
    fun setFloat(id: Int, prop: Int, v: Double)
    fun setString(id: Int, prop: Int, v: String)
    fun setColor(id: Int, prop: Int, v: Long)
    fun setEdges(id: Int, prop: Int, top: Float, right: Float, bottom: Float, left: Float)
    fun setEnum(id: Int, prop: Int, v: Int)
    /** [v] is valid only during the call. */
    fun setBytes(id: Int, prop: Int, v: ByteBuffer)
    fun setFrame(id: Int, x: Float, y: Float, width: Float, height: Float)
    fun listen(id: Int, event: Int)
    fun unlisten(id: Int, event: Int)
    /** [args] is valid only during the call. */
    fun command(id: Int, command: Int, args: ByteBuffer)
    fun setRoot(id: Int)
}

private fun ByteBuffer.take(n: Int): ByteBuffer {
    val s = slice().order(ByteOrder.LITTLE_ENDIAN)
    s.limit(n)
    position(position() + n)
    return s
}

private fun ByteBuffer.string(): String {
    val n = int
    val a = ByteArray(n)
    get(a)
    return String(a, Charsets.UTF_8)
}

/** Decodes a batch of ops (see ops/ops.go) into [h]. */
fun nuiDecode(data: ByteBuffer, h: NuiOpHandler) {
    val r = data.order(ByteOrder.LITTLE_ENDIAN)
    val n = r.int
    repeat(n) {
        val code = r.get().toInt() and 0xff
        val id = r.int
        when (code) {
            1 -> h.create(id, r.short.toInt() and 0xffff)
            2 -> h.destroy(id)
            3 -> { val child = r.int; h.insert(id, child, r.int) }
            4 -> h.remove(id, r.int)
            5 -> {
                val prop = r.short.toInt() and 0xffff
                when (val t = r.get().toInt()) {
                    1 -> h.setBool(id, prop, r.get().toInt() != 0)
                    2 -> h.setInt(id, prop, r.long)
                    3 -> h.setFloat(id, prop, r.double)
                    4 -> h.setString(id, prop, r.string())
                    5 -> h.setColor(id, prop, r.long)
                    6 -> h.setEdges(id, prop, r.float, r.float, r.float, r.float)
                    7 -> h.setEnum(id, prop, r.int)
                    8 -> h.setBytes(id, prop, r.take(r.int))
                    else -> error("nui: bad value type $t")
                }
            }
            6 -> h.setFrame(id, r.float, r.float, r.float, r.float)
            7 -> h.listen(id, r.short.toInt() and 0xffff)
            8 -> h.unlisten(id, r.short.toInt() and 0xffff)
            9 -> { val cmd = r.short.toInt() and 0xffff; h.command(id, cmd, r.take(r.int)) }
            10 -> h.setRoot(id)
            else -> error("nui: bad op code $code")
        }
    }
}

/** What a host reports about its root view (see ops.Environment). */
data class NuiEnvironment(
    val width: Float = 0f, val height: Float = 0f,
    val safeTop: Float = 0f, val safeRight: Float = 0f, val safeBottom: Float = 0f, val safeLeft: Float = 0f,
    val keyboard: Float = 0f,
    val scale: Float = 1f,
    val fontScale: Float = 1f,
    val dark: Boolean = false,
    val locale: String = "",
)

/** Writes the little-endian wire format. */
class NuiWriter {
    private var buf = ByteBuffer.allocate(64).order(ByteOrder.LITTLE_ENDIAN)
    private fun room(n: Int) {
        if (buf.remaining() < n) {
            val b = ByteBuffer.allocate(maxOf(buf.capacity() * 2, buf.position() + n)).order(ByteOrder.LITTLE_ENDIAN)
            buf.flip()
            b.put(buf)
            buf = b
        }
    }
    fun u8(v: Int) { room(1); buf.put(v.toByte()) }
    fun u16(v: Int) { room(2); buf.putShort(v.toShort()) }
    fun u32(v: Int) { room(4); buf.putInt(v) }
    fun u64(v: Long) { room(8); buf.putLong(v) }
    fun f32(v: Float) { room(4); buf.putFloat(v) }
    fun f64(v: Double) { room(8); buf.putDouble(v) }
    fun string(v: String) { val a = v.toByteArray(Charsets.UTF_8); u32(a.size); room(a.size); buf.put(a) }
    fun header(id: Int, kind: Int) { u32(id); u16(kind) }
    fun environment(e: NuiEnvironment) {
        for (f in floatArrayOf(e.width, e.height, e.safeTop, e.safeRight, e.safeBottom, e.safeLeft, e.keyboard, e.scale, e.fontScale)) f32(f)
        u8(if (e.dark) 1 else 0)
        string(e.locale)
    }
    fun gesture(g: NuiGesture) {
        u8(g.state)
        for (f in floatArrayOf(g.x, g.y, g.translationX, g.translationY, g.velocityX, g.velocityY, g.scale)) f32(f)
    }
    fun raw(v: ByteArray) { room(v.size); buf.put(v) }
    fun bytes(): ByteArray = buf.array().copyOf(buf.position())
}

/** A pan or pinch (see ops.Gesture), in points relative to the view. */
data class NuiGesture(
    val state: Int = 0,
    val x: Float = 0f, val y: Float = 0f,
    val translationX: Float = 0f, val translationY: Float = 0f,
    val velocityX: Float = 0f, val velocityY: Float = 0f,
    val scale: Float = 1f,
)
`
